billing(){const q=(billQuery||"").toLowerCase(),L=ORD.filter(o=>(o.source==="Table QR"||o.source==="QR")&&(`${o.no} ${o.customer||""} ${o.tableNo||""}`).toLowerCase().includes(q));return `<div class="hero"><div><h2>Billing · Customer QR orders</h2><span class="mu">Orders placed by guests from enabled table QR menus</span></div><input value="${esc(billQuery)}" data-a="billSearch" placeholder="Search table, order or customer" aria-label="Search QR billing orders"></div><div class="card"><h3>Table order billing <span class="b gr">${L.length} orders</span></h3>${tbl(["Order #","Table","Customer","Items","Order total","Payment","Status"],L.map(o=>["#"+o.no,o.tableNo?"Table QR · Table "+esc(o.tableNo):"Table QR · Table not recorded",esc(o.customer||"QR guest"),o.items.reduce((a,i)=>a+i.q,0)+" items",php(o.tot),o.paymentStatus==="paid"?(o.paym||"Paid"):"Unpaid",bd(orderStatus(o)==="Served"?"ok":orderStatus(o)==="Cancelled"?"er":"wn",orderStatus(o))]),"No customer QR table orders yet. Orders from table QR menus will appear here for billing.")}</div>`},
