async function loadReferenceData(showError=true){
try{
const response=await fetch("/admin/api/reference/dashboard?range="+encodeURIComponent(rng),{headers:{"Accept":"application/json","X-Requested-With":"XMLHttpRequest"}});
if(!response.ok)throw new Error("Reference data request failed ("+response.status+")");
const data=await response.json();
if(Array.isArray(data.menu))MENU=data.menu;
if(Array.isArray(data.ingredients)){ING=data.ingredients;ING.forEach(sync)}
if(Array.isArray(data.orders))ORD=data.orders;
if(Array.isArray(data.waste))WASTE=data.waste;
if(Array.isArray(data.history))HIST=data.history;
if(data.analytics&&data.analytics.range===rng&&page!=="reports")ANALYTICS=data.analytics;
if(Array.isArray(data.purchase_orders)){PO=data.purchase_orders;SUP=[...new Set(PO.map(p=>p.sup).filter(Boolean))]}
if(Array.isArray(data.lots))LOTS=data.lots;
if(Array.isArray(data.tables))TABLES=data.tables;
if(Array.isArray(data.alerts)){ADMIN_ALERTS=data.alerts;renderAdminAlerts()}
if(Array.isArray(data.inquiries)){INQ=data.inquiries;if(!INQ.some(i=>i.id==isel))isel=INQ[0]?.id||0}
if(Array.isArray(data.packages))PKG=data.packages;
if(Array.isArray(data.blackouts))BLOCK=data.blackouts;
if(Array.isArray(data.faqs))FAQ=data.faqs;
if(Array.isArray(data.unanswered))UNA=data.unanswered;
if(Array.isArray(data.users))USERS=data.users;
if(Array.isArray(data.roles)){Object.keys(ROLES).forEach(k=>delete ROLES[k]);data.roles.forEach(role=>{const access=Array.isArray(role.permissions)?role.permissions.map(Boolean):[];access.id=role.id;ROLES[role.name]=access})}
if(Array.isArray(data.rules))RULES=data.rules;
if(Array.isArray(data.logs))LOGS=data.logs;
if(data.settings){Object.assign(SET,data.settings);if(Number.isFinite(+data.settings.recipe_target_percent))SET.tg=+data.settings.recipe_target_percent}
R();
if(page==="reports")loadAnalytics(false);
return true;
}catch(error){if(showError)toast("Unable to load live admin data.");console.error(error);return false}
}
